function palindrome(str) {
  const cleanStr = str.toLowerCase().replace(/[^a-z0-9]/g, '');
  return cleanStr === cleanStr.split('').reverse().join('');
}

function pairElement(str) {
  const pairs = {
    A: 'T',
    T: 'A',
    C: 'G',
    G: 'C'
  };
  return str.split('').map(letter => [letter, pairs[letter]]);
}

function fearNotLetter(str) {
  let alphabet = 'abcdefghijklmnopqrstuvwxyz';
  let startSearch = alphabet.indexOf(str[0]);
  for (let i = 0; i < str.length; i++) {
    if (str[i] !== alphabet[startSearch + i]) {
      return alphabet[startSearch + i];
    }
  }
  return undefined;
}

function chunkArrayInGroups(arr, size) {
  let newArr = [];
  while (arr.length > 0) {
    newArr.push(arr.splice(0, size));
  }
  return newArr;
}

function bouncer(arr) {
  let results = [];
  for (let i = 0; i < arr.length; i++) {
    if (Boolean(arr[i])) {
      results.push(arr[i]);
    }
  }
  return results;
}

function convertHTML(str) {
  const entities = {
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&apos;",
  };
  return str.split('').map(char => entities[char] || char).join('');
}

function largestOfAll(arr) {
  const largestNumbers = [];
  for (let subArr of arr) {
    let max = subArr[0];
    for (let i = 0; i < subArr.length; i++) {
      if (max < subArr[i]) {
        max = subArr[i];
      }
    }
    largestNumbers.push(max);
  }
  return largestNumbers;
}

function mutation(arr) {
  let el1 = arr[0].toLowerCase();
  let el2 = arr[1].toLowerCase();
  for (let i = 0; i < el2.length; i++) {
    if (!el1.includes(el2[i])) {
      return false;
    }
  }
  return true;
}

function reverseString(str) {
  if (!str) return;
  const validatedStr = str.trim();
  let reversed = [];
  for (let i = validatedStr.length - 1; i >= 0; i--) {
    reversed.push(validatedStr[i]);
  }
  return reversed.join('');
}

function findElement(arr, test) {
  for (let el of arr) {
    if (test(el)) return el;
  }
  return undefined;
}

function sumAll(arr) {
  const start = Math.min(...arr);
  const end = Math.max(...arr);
  return Array.from(
    { length: end - start + 1 },
    (_, i) => start + i
  ).reduce((acc, curr) => acc + curr, 0);
}

function titleCase(str) {
  let normalizedstr = str.toLowerCase();
  let words = normalizedstr.split(' ');
  let result = [];
  for (let word of words) {
    let capitalized = word.charAt(0).toUpperCase() + word.slice(1);
    result.push(capitalized);
  }
  return result.join(' ');
}

function frankenSplice(arr1, arr2, index) {
  const result = [...arr2];
  result.splice(index, 0, ...arr1);
  return result;
}

function findLongestWordLength(str) {
  let stringarr = str.split(' ');
  let longest = 0;
  for (let i = 0; i < stringarr.length; i++) {
    if (stringarr[i].length > longest) longest = stringarr[i].length;
  }
  return longest;
}
